{"content": "#!/usr/bin/env python3
"""Cross-check: census descriptor (p_c, N_c, dvals_c) reproduces solver row output
exactly for all q in the sampled rows' computed ranges.  Guards C0071's premise."""
import random
from GROUND_TRUTH import chomp


def load(path="GROUND_TRUTH/cache/census_50000.tsv"):
    D = {}
    with open(path) as f:
        for line in f:
            if line.startswith("#") or line.startswith("r\t"):
                continue
            p = line.rstrip("\n").split("\t")
            D[int(p[0])] = p
    return D


def main():
    D = load()
    random.seed(20261004)
    sample = random.sample([r for r in D if D[r][1] == "live"], 25) + \
             random.sample([r for r in D if D[r][1] == "stale"], 10)
    bad = 0
    checked = 0
    for r in sorted(sample):
        p = D[r]
        cls, per, N = p[1], int(p[2]), int(p[3])
        dvals = [int(x) for x in p[4].split(",")] if p[4] != "-" else []
        deathq = int(p[5]) if p[5] != "-" else None
        dconst = int(p[6]) if p[6] != "-" else None
        qend = int(p[7])
        rows = chomp.row(r, qmax=qend + 50)
        for (q, fv, d) in rows:
            if cls == "live":
                if q < N:
                    continue  # transient: descriptor makes no claim
                pred = q + dvals[(q - N) % per]
            else:
                if q < deathq:
                    continue
                pred = dconst
            checked += 1
            if pred != fv:
                bad += 1
                print(f"MISMATCH r={r} q={q}: solver {fv} vs descriptor {pred}")
    print(f"checked {checked} cells over {len(sample)} rows: {bad} mismatches")


if __name__ == "__main__":
    main()
", "path": "islands/01-recurrence/scratch/desc_crosscheck.py"}

