# Counting inequality test: for every value-window of L consecutive values,
# how many live rows sit in the fiber-span, vs how many values need service?
import math
from collections import Counter
th = 2 - math.sqrt(2); al = 1/th
rows = {}; stale = []
with open("GROUND_TRUTH/cache/census_50000.tsv") as f:
    for line in f:
        if line.startswith("#") or line.startswith("r\t"): continue
        p = line.rstrip("\n").split("\t")
        r = int(p[0])
        if p[1] == "live": rows[r] = (int(p[2]), [int(x) for x in p[4].split(",")])
        else: stale.append(r)
stale_set = set(stale)
p1 = {r for r,(per,dv) in rows.items() if per == 1}
multi = {r for r,(per,dv) in rows.items() if per > 1}

# exact fiber of value v: rows c with v in their value-set (any offset/phase)
valof = {}
for r,(per,dv) in rows.items():
    for v in set(dv):
        valof.setdefault(v, []).append(r)
G = sorted(valof)

# for each maximal G-run of length L, print live rows in span vs service
runs = []
cur = [G[0]]
for i in range(1, len(G)):
    if G[i] == G[i-1]+1: cur.append(G[i])
    else: runs.append(cur); cur=[G[i]]
runs.append(cur)
print("G-runs of length>=5:", [(r[0], len(r)) for r in runs if len(r)>=5])

for run in [r for r in runs if len(r)>=6]:
    v0, v1 = run[0], run[-1]
    c0 = int((v0-1.5)*al) - 3; c1 = int((v1+0.5)*al) + 3
    span = [c for c in range(c0, c1+1)]
    lives = [c for c in span if c in rows]
    stales = [c for c in span if c in stale_set]
    servers = {}
    for v in run:
        servers[v] = [r for r in valof[v] if c0 <= r <= c1]
    print(f"\nrun v={v0}..{v1} len {len(run)}  span c=[{c0},{c1}] ({len(span)} ints) "
          f"stale {len(stales)} live {len(lives)} (p1 {sum(1 for c in lives if c in p1)}, multi {sum(1 for c in lives if c in multi)})")
    print("   services (value -> in-span rows):", {v: rs for v, rs in list(servers.items())[:9]})
    outside = sum(1 for v,rs in servers.items() if not rs)
    print(f"   values with NO in-span server: {outside}")
EOF", "timeout": 300}

