# Descent-free test: does any row's tail word v satisfy v(psi+d)-v(psi) = -d
# for some psi and 1 <= d <= 5?  (If none: every run has distinct witnesses, structurally.)
from collections import Counter
rows = []
with open("GROUND_TRUTH/cache/census_50000.tsv") as f:
    for line in f:
        if line.startswith("#") or line.startswith("r\t"): continue
        p = line.rstrip("\n").split("\t")
        if p[1] == "live":
            rows.append((int(p[0]), int(p[2]), [int(x) for x in p[4].split(",")]))
viol = Counter()
examples = []
for (c, per, dv) in rows:
    for psi in range(per):
        for d in range(1, 6):
            v1 = dv[psi]; v2 = dv[(psi + d) % per]
            if v2 - v1 == -d:
                viol[d] += 1
                if len(examples) < 10: examples.append((c, per, dv, psi, d))
print("rows with v(psi+d)-v(psi) == -d:", dict(viol), " total rows", len(rows))
for e in examples: print("  ", e)
# also: any word with |max-min| > 5?
w = max(max(dv)-min(dv) for (_,_,dv) in rows)
print("max band width:", w)
# and the full difference profile at each d
for d in range(1, 7):
    cnt = Counter()
    for (c, per, dv) in rows:
        for psi in range(per):
            cnt[dv[(psi+d) % per] - dv[psi]] += 1
    top = dict(sorted(cnt.items(), key=lambda kv: -kv[1])[:8])
    print(f"d={d} differences: {top}")
EOF", "timeout": 300}

