# Verify the single-top-per-row lemma on the full table (transients + stale included):
# no value p occurs at two cells (q1,c), (q2,c) with q1<q2 and p>=q2.
from GROUND_TRUTH import chomp
from collections import defaultdict
bad = 0
for R in (60, 120):
    tab = chomp.table(R, 3*R)
    for c in range(0, R+1):
        seen = {}
        for q in range(0, 3*R):
            p = tab[c][q]
            if p in seen and p >= q:
                bad += 1
                if bad < 6: print("VIOLATION", c, seen[p], q, p)
            # record FIRST occurrence
            if p not in seen: seen[p] = q
    print(f"R={R}: violations so far {bad}")
# also the diagonal distinctness premise
d = [tab[c][c] for c in range(121)] if R == 120 else None
print("diagonal distinct:", len(set(d)) == len(d))
EOF", "timeout": 300}

