# Test generation rules for the p1 value sequence v_c against the data.
import math
th = 2 - math.sqrt(2)
rows = {}
stale = []
with open("GROUND_TRUTH/cache/census_50000.tsv") as f:
    for line in f:
        if line.startswith("#") or line.startswith("r\t"): continue
        p = line.rstrip("\n").split("\t")
        if p[1] == "live" and int(p[2]) == 1:
            rows[int(p[0])] = int(p[4])
        elif p[1] == "stale":
            stale.append(int(p[0]))
cs = sorted(rows)
print("p1 rows:", len(cs))

# rule A: v_c = round(th*c)+1 if free else round(th*c)
taken = set()
mismA = []
for c in cs:
    hi = round(th*c) + 1; lo = round(th*c)
    v = hi if hi not in taken else (lo if lo not in taken else None)
    if v != rows[c]:
        if len(mismA) < 8: mismA.append((c, rows[c], v, lo, hi))
    taken.add(rows[c])
print("rule A (hi-first, greedy) mismatches:", len(mismA), mismA[:5])

# rule B: v_c = round(th*c) if free else round(th*c)+1
taken = set()
mismB = []
for c in cs:
    lo = round(th*c); hi = lo + 1
    v = lo if lo not in taken else (hi if hi not in taken else None)
    if v != rows[c]:
        if len(mismB) < 8: mismB.append((c, rows[c], v))
    taken.add(rows[c])
print("rule B (lo-first, greedy) mismatches:", len(mismB), mismB[:5])

# rule C: independent of p1-only: consider ALL live rows arriving in order,
# multi rows contribute their full dvals sets, p1 rows greedily hi-first.
rows_all = []
with open("GROUND_TRUTH/cache/census_50000.tsv") as f:
    for line in f:
        if line.startswith("#") or line.startswith("r\t"): continue
        p = line.rstrip("\n").split("\t")
        if p[1] == "live":
            rows_all.append((int(p[0]), int(p[2]), [int(x) for x in p[4].split(",")]))
rows_all.sort()
taken = set(); mismC = []
for (c, per, dv) in rows_all:
    if per == 1:
        hi = round(th*c) + 1; lo = round(th*c)
        v = hi if hi not in taken else (lo if lo not in taken else None)
        if v != dv[0] and len(mismC) < 8: mismC.append((c, dv[0], v))
        taken.add(dv[0])
    else:
        taken |= set(dv)
print("rule C (all rows, multi contribute sets, p1 greedy hi-first) mismatches:", len(mismC), mismC[:5])

# rule D: mex of taken so far restricted to {lo, hi}:  v = min{lo,hi} - taken
taken = set(); mismD = []
for (c, per, dv) in rows_all:
    if per == 1:
        lo = round(th*c); hi = lo + 1
        cand = [x for x in (lo, hi) if x not in taken]
        v = cand[0] if cand else None
        if v != dv[0] and len(mismD) < 8: mismD.append((c, dv[0], v))
        taken.add(dv[0])
    else:
        taken |= set(dv)
print("rule D (lo-first over all rows) mismatches:", len(mismD), mismD[:5])
EOF", "timeout": 300}

