# Dissect the windows with 8 live rows in 16 consecutive ints: why no p1 8-run there?
import math
from collections import Counter
th = 2 - math.sqrt(2); al = 1/th
live = {}; 
with open("/tmp/c100k.tsv") as f:
    for line in f:
        if line.startswith("#") or line.startswith("r\t"): continue
        p = line.rstrip("\n").split("\t")
        if p[1] == "live":
            live[int(p[0])] = (int(p[2]), [int(x) for x in p[4].split(",")])
n = 100001
windows = []
for x in range(0, n - 16):
    cs = [c for c in range(x, x+16) if c in live]
    if len(cs) == 8:
        windows.append((x, cs))
print("windows with 8 live in 16:", len(windows))
allp1 = 0
for (x, cs) in windows:
    if all(live[c][0] == 1 for c in cs): allp1 += 1
print("of these, all 8 rows period-1:", allp1)

# for all-p1 windows: can the 8 rows carry 8 consecutive values?
# row c can carry v in {round(th c), round(th c)+1}; need injective assignment of 8 consecutive v.
def ok_consec(cs):
    # bipartite: values v..v+7 vs rows; row c eligible for v if round(th*c) in {v, v-1}
    cs = sorted(cs)
    lo = min(round(th*c) for c in cs) 
    for v0 in range(lo-2, lo+3):
        # greedy matching check via simple backtracking
        def match(i, used, taken_v):
            if i == len(cs): return True
            c = cs[i]
            for v in (v0+i,):
                if v not in taken_v and round(th*c) in (v, v-1):
                    taken_v.add(v)
                    if match(i+1, used, taken_v): return True
                    taken_v.remove(v)
            return False
        if match(0, 0, set()): return v0
    return None
cnt = Counter()
examples = []
for (x, cs) in windows:
    if all(live[c][0] == 1 for c in cs):
        v0 = ok_consec(cs)
        cnt[v0 is not None] += 1
        if v0 is not None and len(examples) < 6: examples.append((x, cs, v0))
print("all-p1 windows where 8 consecutive values are assignable:", dict(cnt))
print("assignable examples (window start, rows, first value):", examples)
EOF", "timeout": 300}

