# Are the all-p1 heptads exactly value-blocks x 72 phases?  Distinct h0 among all-p1 heptads.
import math
from collections import Counter
Q = 72
rows = []
with open("/tmp/c100k.tsv") as f:
    for line in f:
        if line.startswith("#") or line.startswith("r\t"): continue
        p = line.rstrip("\n").split("\t")
        if p[1] == "live":
            rows.append((int(p[0]), int(p[2]), int(p[3]), [int(x) for x in p[4].split(",")]))
U = [dict() for _ in range(Q)]
per_of = {}
for (c, per, N, dv) in rows:
    per_of[c] = per
    for phi in range(Q):
        U[phi].setdefault(dv[(phi - N) % per], c)
def runlen(phi0, h0, cap=10):
    L, h, phi = 0, h0, phi0
    while h >= 0 and h in U[phi] and L < cap:
        L += 1; h -= 1; phi = (phi+1) % Q
    return L
sev = [(phi0, h0) for phi0 in range(Q) for h0 in U[phi0] if runlen(phi0, h0) == 7]
allp1_h0 = set(); mixed_h0 = set()
for (phi0, h0) in sev:
    wits = []
    h, phi = h0, phi0
    for j in range(7):
        wits.append(U[phi][h]); h -= 1; phi = (phi+1) % Q
    if all(per_of[c] == 1 for c in wits):
        allp1_h0.add(h0)
    else:
        mixed_h0.add(h0)
print("all-p1 heptad tops:", sorted(allp1_h0), "-> phases each:",
      Counter(h0 for (p0,h0) in sev if h0 in allp1_h0))
print("mixed heptad tops:", len(mixed_h0), sorted(mixed_h0)[:10], "...")
print("mixed tops phase counts:", Counter(h0 for (p0,h0) in sev if h0 in mixed_h0))
