with open("GROUND_TRUTH/cache/census_50000.tsv") as f:
    for line in f:
        if line.startswith("#") or line.startswith("r\t"): continue
        p = line.rstrip("\n").split("\t")
        r = int(p[0])
        if p[1] == "stale": cls[r] = "S"
        else:
            cls[r] = "P" if int(p[2]) == 1 else "M"
delta = {}
for r, k in cls.items():
    if k == "P":
        pass
# need values for p1 rows
vals = {}
with open("GROUND_TRUTH/cache/census_50000.tsv") as f:
    for line in f:
        if line.startswith("#") or line.startswith("r\t"): continue
        p = line.rstrip("\n").split("\t")
        r = int(p[0])
        if p[1] == "live" and int(p[2]) == 1:
            vals[r] = int(p[4])
for r, v in vals.items():
    delta[r] = v - round(th*r)
print("p1 rows:", len(delta), "dips:", sum(1 for d in delta.values() if d == 0))

for k in (1, 2, 3, 4, 5):
    groups = defaultdict(Counter)
    for r in delta:
        pat = "".join(cls.get(r + i, "?") for i in range(-k, k + 1))
        groups[pat][delta[r]] += 1
    amb = {p: c for p, c in groups.items() if len(c) > 1}
    n_amb_rows = sum(sum(c.values()) for c in amb.values())
    print(f"k={k}: {len(groups)} patterns, ambiguous patterns {len(amb)} "
          f"covering {n_amb_rows} rows of {len(delta)}")
    if amb and k <= 2:
        for p, c in list(amb.items())[:6]:
