    n_amb_rows = sum(sum(c.values()) for c in amb.values())
    print(f"  k={k}: {len(groups)} patterns, ambiguous {len(amb)} covering {n_amb_rows} rows")
    if amb and k == 1:
        for p, c in list(amb.items())[:8]:
            print(f"    {p}: {dict(c)}")
