# Resolution-length test: conflicting pairs at k=18 -- how far must we look to distinguish them?
from collections import Counter, defaultdict
import math
th = 2 - math.sqrt(2)
cls = {}; vals = {}
with open("GROUND_TRUTH/cache/census_50000.tsv") as f:
    for line in f:
        if line.startswith("#") or line.startswith("r\t"): continue
        p = line.rstrip("\n").split("\t")
        r = int(p[0])
        if p[1] == "stale": cls[r] = "S"
        else:
            if int(p[2]) == 1: cls[r] = "P"; vals[r] = int(p[4])
            else: cls[r] = "M"
delta = {r: vals[r] - round(th*r) for r in vals}
rows_ = sorted(delta)
lo, hi_r = min(cls), max(cls)
K = 18
pat_rows = defaultdict(list)
for r in rows_:
    if r - K < lo or r + K > hi_r: continue
    pat_rows["".join(cls[r + i] for i in range(-K, K+1))].append(r)
mixed = {p: rs for p, rs in pat_rows.items() if len(rs) > 1 and len({delta[r] for r in rs}) > 1}
print(f"mixed W18 groups: {len(mixed)}, rows: {sum(len(rs) for rs in mixed.values())}")
res = Counter()
unres = []
for p, rs in mixed.items():
    dips = [r for r in rs if delta[r] == 0]
    norms = [r for r in rs if delta[r] == 1]
    for r1 in dips[:3]:
        for r2 in norms[:3]:
            k = K
            while k < 60 and all(cls.get(r1+i) == cls.get(r2+i) for i in range(-k, k+1)):
                k += 1
            if k >= 60:
                unres.append((r1, r2))
                res["unresolved to 60"] += 1
            else:
                res[k] += 1
print("resolution length histogram (pair distinguished at W_k):", dict(sorted(res.items(), key=lambda kv: str(kv[0]))))
print("unresolved pairs:", unres[:8])
# for unresolved pairs: how far apart are the rows? and do they share cls exactly forever?
for (r1, r2) in unres[:5]:
    same = sum(1 for i in range(-60, 61) if cls.get(r1+i) == cls.get(r2+i))
    print(f"  pair ({r1},{r2}) dist {r2-r1}: {same}/121 class cells equal in +-60")
EOF", "timeout": 600}

