# Vacuity control: mixed-group counts at k=29,30 for REAL delta vs SHUFFLED delta.
from collections import Counter, defaultdict
import math, random
th = 2 - math.sqrt(2)
def load(path):
    cls = {}; vals = {}
    with open(path) as f:
        for line in f:
            if line.startswith("#") or line.startswith("r\t"): continue
            p = line.rstrip("\n").split("\t")
            r = int(p[0])
            if p[1] == "stale": cls[r] = "S"
