                if int(p[2]) == 1: cls[r] = "P"; vals[r] = int(p[4])
                else: cls[r] = "M"
    return cls, {r: vals[r] - round(th*r) for r in vals}
cls, delta = load("/tmp/c100k.tsv")
rows_ = sorted(delta)
dvals = [delta[r] for r in rows_]
random.seed(20261004)
def mixed_groups(assign, k):
    groups = defaultdict(Counter)
    for r in rows_:
        if r - k < 0: continue
        groups["".join(cls[r + i] for i in range(-k, k+1))][assign[r]] += 1
