    sh = []
    for t in range(5):
        dv = dvals[:]; random.shuffle(dv)
        sh.append(mixed_groups({r: dv[i] for i, r in enumerate(rows_)}, k))
    avg = tuple(sum(s[i] for s in sh)/5 for i in range(3))
    print(f"k={k}: REAL mixed {real[0]} groups ({real[1]} rows, {real[2]} groups) | "
