# Information localization: null deltas from radius-k context rates -- at which k does the
# 8-run disappear?
import math, random
from collections import Counter, defaultdict
th = 2 - math.sqrt(2)
cls = {}; vals = {}
with open("islands/01-recurrence/scratch/census_100000.tsv") as f:
    for line in f:
        if line.startswith("#") or line.startswith("r\t"): continue
        p = line.rstrip("\n").split("\t")
        r = int(p[0])
        if p[1] == "stale": cls[r] = "S"
        else:
            if int(p[2]) == 1: cls[r] = "P"; vals[r] = int(p[4])
            else: cls[r] = "M"
delta = {r: vals[r] - round(th*r) for r in vals}
rows = sorted(cls)
idxr = {r: i for i, r in enumerate(rows)}
def ctx(r, k):
    i = idxr[r]
    return "".join(rows[j] for j in range(i-k, i+k+1) if 0 <= j < len(rows) and j != i) if False else \
           "".join(cls[rows[i+j]] if 0 <= i+j < len(rows) else "?" for j in range(-k, k+1))
def synth(rng, k, n=20000, block=60, trials=20):
    # context rates at radius k (center letter position k)
    rate = defaultdict(lambda: [0,0])
    for r in delta:
        key = ctx(r, k)
        rate[key][1] += 1
        if delta[r] == 0: rate[key][0] += 1
    outs = []
    for t in range(trials):
        word = {}
        pos = 0
        while pos < n:
            s = rng.randrange(0, max(1, len(rows)-block))
            for i in range(block):
                word[pos] = cls[rows[(s+i) % len(rows)]]
                pos += 1
                if pos >= n: break
        d = {}
        for c in range(k+1, n-k-1):
            if word[c] != 'P': continue
            key = "".join(word[j] for j in range(c-k, c+k+1))
            dd, nn = rate.get(key, (0, 2))
            p = dd/nn if nn else 0.05
            d[c] = 0 if rng.random() < p else 1
        V = sorted(round(th*c) + d[c] for c in d)
        best = cur = 0
        for i in range(1, len(V)):
            cur = cur+1 if V[i] == V[i-1]+1 else 1
            best = max(best, cur)
        outs.append(best)
    return outs
rng = random.Random(20261004)
for k in (2, 3, 4, 5, 6):
    res = synth(rng, k)
    print(f"radius-{k} null: max runs {dict(sorted(Counter(res).items()))} | >=8 in {sum(1 for x in res if x>=8)}/{len(res)} trials")
print("real word: max 7 (F-blocks), 0 octads")
